                                className="w-full bg-white/5 border border-white/10 rounded-lg p-2 text-xs focus:outline-none focus:border-luxury-gold/50" />
                            </div>
                            <div className="space-y-1">
                              <label className="text-[10px] text-white/40">رابط صورة</label>
                              <input type="text" value={car.images?.[0] || ''} onChange={e => updateCar(index, 'images', e.target.value ? [e.target.value] : [])}
                                placeholder="https://..." dir="ltr"
                                className="w-full bg-white/5 border border-white/10 rounded-lg p-2 text-xs focus:outline-none focus:border-luxury-gold/50 text-left font-mono" />
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>

              {/* أزرار الحفظ */}
              <div className="p-6 border-t border-white/5 flex gap-3 shrink-0">
                <button type="button" onClick={handleSave} disabled={isLoading}
                  className="flex-1 py-3.5 bg-luxury-gold text-black font-black text-sm rounded-xl hover:bg-white transition-all shadow-[0_0_20px_rgba(212,175,55,0.15)] cursor-pointer disabled:opacity-50">
                  {isLoading ? <Loader2 className="w-4 h-4 animate-spin inline" /> : 'حفظ الجلسة'}
                </button>
                <button type="button" onClick={() => { setIsModalOpen(false); resetForm(); }}
                  className="px-6 py-3.5 bg-white/5 text-white/60 hover:text-white hover:bg-white/10 border border-white/10 rounded-xl text-sm font-bold transition-all cursor-pointer">
                  إلغاء
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Eye, X, CheckCircle2, Clock, XCircle, AlertCircle, ShoppingBag, User, CreditCard, Loader2, RefreshCw } from 'lucide-react';

import { api } from '../../../lib/api';

export default function AdminOrdersPage() {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<any>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [updatingStatus, setUpdatingStatus] = useState(false);
  const [alert, setAlert] = useState<{ msg: string; type: 'success' | 'error' } | null>(null);

  const fetchOrders = async () => {
    setLoading(true);
    try {
      const res = await api.orders.getAll();
      if (res.data) {
        const d = res.data as any;
        const ordersList = Array.isArray(d?.data)
          ? d.data
          : Array.isArray(d)
            ? d
            : (d?.data?.orders || d?.orders || []);
        setOrders(ordersList);
      }
    } catch (err) {
      console.error('Failed to fetch orders', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  const openOrderDetails = async (orderId: string) => {
    try {
      const res = await api.orders.getById(orderId);
      if (res.data && (res.data as any).success) {
        setSelectedOrder((res.data as any).data);
        setModalOpen(true);
      }
    } catch (err) {
      console.error('Failed to fetch order details', err);
    }
  };

  const handleStatusChange = async (status: string) => {
    if (!selectedOrder) return;
    setUpdatingStatus(true);
    setAlert(null);
    try {
      const res = await api.orders.updateStatus(selectedOrder._id, status);
      if (res.data && (res.data as any).success) {
        setAlert({ msg: 'تم تحديث حالة الطلب بنجاح!', type: 'success' });
        setSelectedOrder((prev: any) => ({ ...prev, status }));
        // Refresh local orders list
        fetchOrders();
      } else {
        throw new Error('فشل تحديث الحالة');
      }
    } catch (err: any) {
      setAlert({ msg: err.message || 'حدث خطأ أثناء تحديث حالة الطلب', type: 'error' });
    } finally {
      setUpdatingStatus(false);
    }
  };

  const STATUS_CONFIG: Record<string, { label: string; icon: any; cls: string }> = {
    pending:    { label: 'قيد الانتظار',  icon: Clock,        cls: 'text-yellow-400 bg-yellow-400/10 border border-yellow-400/20' },
    processing: { label: 'قيد المعالجة', icon: RefreshCw,    cls: 'text-blue-400 bg-blue-400/10 border border-blue-400/20' },
    completed:  { label: 'مكتمل',         icon: CheckCircle2, cls: 'text-green-400 bg-green-400/10 border border-green-400/20' },
    approved:   { label: 'مقبول',         icon: CheckCircle2, cls: 'text-emerald-400 bg-emerald-400/10 border border-emerald-400/20' },
    cancelled:  { label: 'ملغي',          icon: XCircle,      cls: 'text-red-400 bg-red-400/10 border border-red-400/20' },
    rejected:   { label: 'مرفوض',        icon: AlertCircle,  cls: 'text-red-500 bg-red-500/10 border border-red-500/20' },
  };

  const getStatusBadge = (status: string) => {
    const cfg = STATUS_CONFIG[status] || STATUS_CONFIG['pending'];
    const Icon = cfg.icon;
    return (
      <span className={`inline-flex items-center gap-1.5 text-xs font-bold px-3 py-1.5 rounded-full ${cfg.cls}`}>
        <Icon className="w-3.5 h-3.5" /> {cfg.label}
      </span>
    );
  };

  const [statusFilter, setStatusFilter] = useState<string>('all');

  const filteredOrders = orders.filter(order => {
    const term = searchTerm.toLowerCase();
    const orderNum = order.orderNumber || order._id || '';
    const buyerName = order.buyer?.name || '';
    const matchesSearch = orderNum.toLowerCase().includes(term) || buyerName.toLowerCase().includes(term);
    const matchesStatus = statusFilter === 'all' || order.status === statusFilter;
    return matchesSearch && matchesStatus;
