            {/* ── زر الاستيراد التلقائي (للقطع المستوردة فقط) ── */}
            {activeSection === 'imported' && (
              <div className="bg-gradient-to-br from-blue-500/5 to-transparent border border-blue-500/15 rounded-2xl p-6 space-y-4">
                <div className="flex items-start justify-between gap-4 flex-wrap">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <Globe className="w-4 h-4 text-blue-400" />
                      <h3 className="text-sm font-black text-white">استيراد تلقائي من AutoSpare</h3>
                    </div>
                    <p className="text-white/30 text-xs leading-relaxed max-w-md">
                      يجلب جميع <strong className="text-white/60">الوكالات</strong> (الاسم + الشعار) وقطع كل وكالة (الاسم + الصورة) —
                      {' '}<strong className="text-white/60">بدون سعر</strong>، الطلب يكون عبر WhatsApp.
                    </p>
                  </div>
                  <AutoSpareImportButton onImported={fetchParts} />
                </div>
                <div className="flex flex-wrap gap-3 pt-2 border-t border-white/5">
                  <div className="flex items-center gap-1.5 text-[10px] text-white/30 font-medium">
                    <CheckCircle2 className="w-3 h-3 text-green-400" />
                    شعارات الوكالات محفوظة
                  </div>
                  <div className="flex items-center gap-1.5 text-[10px] text-white/30 font-medium">
                    <Download className="w-3 h-3 text-blue-400" />
                    صور القطع + علامة مائية HM CAR
                  </div>
                  <div className="flex items-center gap-1.5 text-[10px] text-white/30 font-medium">
                    <RefreshCw className="w-3 h-3 text-luxury-gold" />
                    السعر: «اطلب عبر WhatsApp»
                  </div>
                </div>
              </div>
            )}

            {error && (
              <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl text-red-500 text-center text-sm font-bold">
                {error}
              </div>
            )}

            {/* Search */}
            <div className="flex flex-col md:flex-row gap-3">
              <div className="relative flex-1">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-white/20" />
                <input
                  type="text"
                  placeholder="ابحث عن قطعة غيار بالاسم أو الماركة..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full bg-white/5 border border-white/10 rounded-xl py-3 pr-11 pl-4 text-sm focus:outline-none focus:border-luxury-gold/40 transition-all text-right"
                  dir="rtl"
                />
              </div>
            </div>

            {/* Table */}
            {loading ? (
              <div className="bg-white/[0.02] border border-white/10 rounded-3xl p-12 text-center">
                <div className="w-12 h-12 border-2 border-luxury-gold/30 border-t-luxury-gold rounded-full animate-spin mx-auto mb-4" />
                <p className="text-white/40 text-sm">جاري تحميل قطع الغيار...</p>
              </div>
            ) : filteredParts.length === 0 ? (
              <div className="bg-white/[0.02] border border-white/10 rounded-3xl p-16 text-center">
                <Wrench className="w-12 h-12 text-white/10 mx-auto mb-4" />
                <h3 className="text-xl font-bold mb-2">لا توجد قطع غيار</h3>
                <p className="text-white/40 text-sm">
                  {activeSection === 'imported'
                    ? 'لا توجد قطع غيار مستوردة في هذا القسم بعد.'
                    : 'لا توجد قطع غيار مضافة يدوياً. اضغط على "إضافة قطعة غيار جديدة" لإضافة أولى.'}
                </p>
              </div>
            ) : (
              <div className="bg-white/[0.02] border border-white/10 rounded-3xl overflow-hidden backdrop-blur-xl">
                <div className="overflow-x-auto">
                  <table className="w-full text-right" dir="rtl">
                    <thead>
                      <tr className="bg-white/5 border-b border-white/10">
                        <th className="px-6 py-4 text-xs font-bold text-white/40 uppercase tracking-widest">القطعة</th>
                        <th className="px-6 py-4 text-xs font-bold text-white/40 uppercase tracking-widest">الماركة المستهدفة</th>
                        <th className="px-6 py-4 text-xs font-bold text-white/40 uppercase tracking-widest">السعر</th>
                        <th className="px-6 py-4 text-xs font-bold text-white/40 uppercase tracking-widest">حالة التوفر</th>
                        <th className="px-6 py-4 text-xs font-bold text-white/40 uppercase tracking-widest">المخزون (الكمية)</th>
                        <th className="px-6 py-4 text-xs font-bold text-white/40 uppercase tracking-widest">الإجراءات</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                      {filteredParts.map((part) => (
                        <tr key={part._id} className="hover:bg-white/[0.01] transition-colors">
                          {/* Name & Photo */}
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center gap-3">
                              <div className="w-12 h-12 rounded-xl bg-white/5 border border-white/10 overflow-hidden flex items-center justify-center shrink-0">
                                <SafePartImage
                                  src={part.img || part.image || part.images?.[0]}
                                  alt={part.name}
                                  className="w-full h-full object-cover"
                                />
                              </div>
                              <div>
                                <div className="font-bold text-white">{part.name}</div>
                                <div className="text-xs text-white/30 mt-0.5">{part.partType || 'قطعة غيار'}</div>
                              </div>
                            </div>
                          </td>

                          {/* Brand */}
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-white/60">
                            {part.brand?.name || part.carMake || 'عالمي'}
                          </td>

                          {/* Price */}
                          <td className="px-6 py-4 whitespace-nowrap font-bold text-luxury-gold">
                            {part.price ? `${part.price.toLocaleString()} ر.س` : 'اتصل للسعر'}
                          </td>

                          {/* In Stock toggle */}
                          <td className="px-6 py-4 whitespace-nowrap">
                            <button
                              onClick={() => handleToggleStock(part)}
                              className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold transition-all ${
                                part.inStock
                                  ? 'bg-green-500/10 text-green-400 border border-green-500/20 hover:bg-green-500/20'
                                  : 'bg-red-500/10 text-red-400 border border-red-500/20 hover:bg-red-500/20'
                              }`}
                            >
                              {part.inStock ? (
                                <>
                                  <CheckCircle2 className="w-3.5 h-3.5" />
                                  متوفر
                                </>
                              ) : (
                                <>
                                  <XCircle className="w-3.5 h-3.5" />
                                  غير متوفر
                                </>
                              )}
                            </button>
                          </td>

                          {/* Stock Quantity */}
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-white/60">
                            {part.stockQty ?? 0}
                          </td>

                          {/* Actions */}
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center gap-3">
                              <Link
                                href={`/parts/${part._id}`}
                                target="_blank"
                                className="p-2 bg-white/5 border border-white/10 rounded-lg text-white/60 hover:text-white transition-colors"
                                title="عرض في المتجر"
                              >
                                <ExternalLink className="w-4 h-4" />
                              </Link>
                              <Link
                                href={`/admin/parts/${part._id}`}
                                className="p-2 bg-white/5 border border-white/10 rounded-lg text-white/60 hover:text-luxury-gold hover:border-luxury-gold/30 transition-all"
                                title="تعديل"
                              >
                                <Edit2 className="w-4 h-4" />
                              </Link>
                              <button
                                onClick={() => handleDelete(part._id)}
                                className="p-2 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400 hover:bg-red-500 hover:text-white transition-all"
                                title="حذف"
                              >
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Save, Settings, Globe, Shield, CreditCard, Bell, Share2, Upload, Sparkles, Loader2, CheckCircle, AlertCircle } from 'lucide-react';

import { api } from '../../../lib/api';
import { uploadImage } from '../../../lib/cloudinary';
import SyncWatermarksButton from '../../../components/admin/SyncWatermarksButton';

export default function AdminSettingsPage() {
  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('general');
  const [successMsg, setSuccessMsg] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [imageUploading, setImageUploading] = useState(false);

  // Forms Data
  const [generalData, setGeneralData] = useState({
    title: 'CAR X',
    description: 'المعرض الحصري للسيارات الفاخرة',
    phone: '',
    email: ''
  });

  const [socialData, setSocialData] = useState({
    salesWhatsapp: '',
    auctionWhatsapp: '',
    supportWhatsapp: '',
    whatsapp: '',
    facebook: '',
    instagram: '',
    twitter: '',
    tiktok: '',
    snapchat: '',
    youtube: ''
  });

  const [brandData, setBrandData] = useState({
    logo: '',
    heroVideoUrl: ''
  });

  const [securityData, setSecurityData] = useState({
    deviceLockEnabled: true,
    maintenanceMode: false
  });

  useEffect(() => {
    const fetchSettings = async () => {
      setInitialLoading(true);
      try {
        const res = await api.settings.get();
        if (res.data && (res.data as any).success) {
          const settings = (res.data as any).data;

          setGeneralData({
            title: settings.siteInfo?.name || 'CAR X',
            description: settings.siteInfo?.description || 'المعرض الحصري للسيارات الفاخرة',
            phone: settings.contactInfo?.phone || '',
            email: settings.contactInfo?.email || ''
          });

          const carx = settings.homeContent?.carxSettings || {};
          setSocialData({
            salesWhatsapp: carx.salesWhatsapp || settings.contactInfo?.whatsapp || '',
            auctionWhatsapp: carx.auctionWhatsapp || settings.contactInfo?.whatsapp || '',
            supportWhatsapp: carx.supportWhatsapp || settings.contactInfo?.whatsapp || '',
            whatsapp: settings.contactInfo?.whatsapp || settings.socialLinks?.whatsapp || carx.salesWhatsapp || '',
            facebook: settings.socialLinks?.facebook || '',
            instagram: settings.socialLinks?.instagram || '',
            twitter: settings.socialLinks?.twitter || '',
            tiktok: settings.socialLinks?.tiktok || '',
            snapchat: settings.socialLinks?.snapchat || '',
            youtube: settings.socialLinks?.youtube || ''
          });

          setBrandData({
            logo: settings.siteInfo?.logo || '',
            heroVideoUrl: carx.heroVideoUrl || '/videos/CAR_X.mp4'
          });

          setSecurityData({
            deviceLockEnabled: carx.deviceLockEnabled !== false,
            maintenanceMode: settings.features?.maintenanceMode || false
          });
        }
      } catch (err) {
        console.error('Failed to fetch settings:', err);
        setErrorMsg('حدث خطأ أثناء تحميل الإعدادات');
      } finally {
        setInitialLoading(false);
      }
    };
    fetchSettings();
  }, []);

  const handleGeneralChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setGeneralData(prev => ({ ...prev, [name]: value }));
  };

  const handleSocialChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setSocialData(prev => ({ ...prev, [name]: value }));
  };

  const handleBrandChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBrandData(prev => ({ ...prev, [name]: value }));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageUploading(true);
      setErrorMsg('');
      try {
        const url = await uploadImage(file);
        setBrandData(prev => ({ ...prev, logo: url }));
        setSuccessMsg('تم رفع الشعار الجديد بنجاح');
      } catch (err: any) {
        setErrorMsg(err.message || 'فشل رفع الشعار');
      } finally {
        setImageUploading(false);
      }
    }
  };

  const showToast = (msg: string, isError = false) => {
    if (isError) {
      setErrorMsg(msg);
      setTimeout(() => setErrorMsg(''), 5000);
    } else {
      setSuccessMsg(msg);
      setTimeout(() => setSuccessMsg(''), 5000);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg('');
    setSuccessMsg('');

    try {
      if (activeTab === 'general') {
        const res1 = await api.settings.updateSiteInfo({
          name: generalData.title,
          description: generalData.description,
          logo: brandData.logo
        });
        const res2 = await api.settings.updateContactInfo({
          phone: generalData.phone,
          email: generalData.email,
          whatsapp: socialData.salesWhatsapp
        });

        if (res1.error || res2.error) throw new Error(res1.error || res2.error);
        showToast('تم حفظ الإعدادات العامة بنجاح!');
      } 
      else if (activeTab === 'social') {
        // Save WhatsApp numbers in CarX settings
        const resCarX = await api.settings.updateCarX({
          salesWhatsapp: socialData.salesWhatsapp,
          auctionWhatsapp: socialData.auctionWhatsapp,
          supportWhatsapp: socialData.supportWhatsapp,
          heroVideoUrl: brandData.heroVideoUrl
        });
        // Save social links
        const resSocial = await api.settings.updateSocialLinks({
          whatsapp: socialData.whatsapp || socialData.salesWhatsapp,
          facebook: socialData.facebook,
          instagram: socialData.instagram,
          twitter: socialData.twitter,
          tiktok: socialData.tiktok,
          snapchat: socialData.snapchat,
          youtube: socialData.youtube
        });
        if (resCarX.error) throw new Error(resCarX.error);
        if (resSocial.error) throw new Error(resSocial.error);
        showToast('تم حفظ جميع روابط التواصل الاجتماعي بنجاح!');
      }
      else if (activeTab === 'brand') {
        const res = await api.settings.updateCarX({
          heroVideoUrl: brandData.heroVideoUrl
        });
        const resLogo = await api.settings.updateSiteInfo({
          name: generalData.title,
          description: generalData.description,
          logo: brandData.logo
        });
        if (res.error || resLogo.error) throw new Error(res.error || resLogo.error);
        showToast('تم تحديث هوية المعارض والشعار السحابي بنجاح!');
      }
      else if (activeTab === 'security') {
        const res = await api.settings.updateCarX({
          deviceLockEnabled: securityData.deviceLockEnabled
        });
        if (res.error) throw new Error(res.error);
        showToast('تم تحديث الخيارات الأمنية والتشغيلية بنجاح!');
      }
    } catch (err: any) {
      showToast(err.message || 'حدث خطأ غير متوقع أثناء الحفظ', true);
    } finally {
      setLoading(false);
    }
  };

  const tabs = [
    { id: 'general', label: 'عام وتواصل', icon: Globe },
    { id: 'social', label: 'الواتساب والاجتماعي', icon: Share2 },
    { id: 'brand', label: 'الهوية والشعار السحابي', icon: Sparkles },
    { id: 'security', label: 'الأمان والتشغيل', icon: Shield },
  ];

  if (initialLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="w-10 h-10 border-4 border-luxury-gold/30 border-t-luxury-gold rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-6" dir="rtl">

        {/* Toast Messages */}
        {successMsg && (
          <div className="fixed bottom-10 left-10 z-50 bg-green-500/20 border border-green-500/30 text-green-400 px-6 py-4 rounded-2xl flex items-center gap-3 backdrop-blur-xl shadow-[0_0_30px_rgba(34,197,94,0.1)]">
            <CheckCircle className="w-5 h-5" />
            <span className="font-bold text-sm">{successMsg}</span>
          </div>
        )}
        {errorMsg && (
          <div className="fixed bottom-10 left-10 z-50 bg-red-500/20 border border-red-500/30 text-red-500 px-6 py-4 rounded-2xl flex items-center gap-3 backdrop-blur-xl shadow-[0_0_30px_rgba(239,68,68,0.1)]">
            <AlertCircle className="w-5 h-5" />
            <span className="font-bold text-sm">{errorMsg}</span>
          </div>
        )}

        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
          <div>
            <h1 className="text-3xl font-black">إعدادات المنصة</h1>
            <p className="text-white/40 text-sm mt-1">تخصيص وإدارة تجربة وهوية CAR X بالكامل</p>
          </div>

          <button 
            type="button"
