                </p>
              </div>

              {/* Trust badge */}
              <div className="p-6 rounded-2xl border border-white/5 flex items-center gap-4 text-white/40" dir="rtl">
                <ShieldCheck className="w-8 h-8 text-luxury-gold/40 shrink-0" />
                <p className="text-xs leading-relaxed">
                  جميع قطع الغيار أصلية ومفحوصة من قبل فريق CAR X المتخصص.
                </p>
              </div>

            </div>
          </div>

        </div>
      </div>

      <Footer />
    </main>
  );
}

'use client';

import Link from 'next/link';
import { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, SlidersHorizontal, Wrench, X, Sparkles, Info } from 'lucide-react';
import Navbar from '../../components/Navbar';
import Footer from '../../components/Footer';
import LuxuryPartCard from '../../components/LuxuryPartCard';
import { api } from '../../lib/api';

const CATEGORIES = ['فلاتر', 'فرامل', 'محرك', 'تعليق', 'كهرباء', 'إضاءة', 'ناقل حركة'];

export default function PartsPage() {
  const [parts, setParts]         = useState<any[]>([]);
  const [loading, setLoading]     = useState(true);
  const [searchTerm, setSearchTerm]           = useState('');
  const [showFilters, setShowFilters]         = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedBrand, setSelectedBrand]     = useState('');
  const [onlyOriginal, setOnlyOriginal]       = useState(false);

  useEffect(() => {
    const fetchParts = async () => {
      setLoading(true);
      try {
        const res = await api.parts.getAll();
        if (res.data) {
          const d = res.data as any;
          const list = Array.isArray(d?.data)
            ? d.data
            : Array.isArray(d)
              ? d
              : (d?.data?.parts || d?.parts || []);
          setParts(list);
        } else {
          setParts([]);
        }
      } catch {
        setParts([]);
      } finally {
        setLoading(false);
      }
    };
    fetchParts();
  }, []);

  const brands = useMemo(() => {
    const set = new Set(parts.map(p => p.brand).filter(Boolean));
    return Array.from(set) as string[];
  }, [parts]);

  const filteredParts = useMemo(() => {
    let result = [...parts];
    if (searchTerm) {
      const q = searchTerm.toLowerCase();
      result = result.filter(p =>
        p.name?.toLowerCase().includes(q) ||
        p.partNumber?.toLowerCase().includes(q) ||
        p.brand?.toLowerCase().includes(q)
      );
    }
    if (selectedCategory) result = result.filter(p => p.category === selectedCategory);
    if (selectedBrand)    result = result.filter(p => p.brand === selectedBrand);
