  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const { login } = useAuth();

  const containerVariants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: 0.08,
        delayChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    show: { 
      opacity: 1, 
      y: 0, 
      transition: { 
        type: 'spring' as const, 
        stiffness: 100, 
        damping: 15 
      } 
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (name.trim().split(/\s+/).length < 2) {
      setError('الرجاء إدخال الاسم الثنائي أو الثلاثي بالكامل (اسمان على الأقل)');
      setLoading(false);
      return;
    }

    if (password !== confirmPassword) {
      setError('كلمات المرور غير متطابقة');
      setLoading(false);
      return;
    }

    if (password.length < 6) {
      setError('يجب أن تتكون كلمة المرور من 6 خانات على الأقل');
      setLoading(false);
      return;
    }

    try {
      const res = await api.auth.register({ name, email, phone, password });

      if (res.error) {
        setError(res.error);
        return;
      }

      const resData = res.data as any;
      // Backend returns { success, token, user, data } at top level
      const token = resData?.token;
      const userData = resData?.user || resData?.data;

      if (resData?.success && token && userData) {
        setSuccess(true);
        login(token, userData);
        setTimeout(() => { window.location.href = '/'; }, 2500);
      } else {
        setError(resData?.message || 'حدث خطأ أثناء إنشاء الحساب');
      }
    } catch (err) {
      setError('حدث خطأ في الاتصال بالخادم');
    } finally {
      setLoading(false);
