'use client';

import { useState, useRef, useCallback } from 'react';
import { Upload, X, Image as ImageIcon, Loader2, AlertCircle, CheckCircle2 } from 'lucide-react';
import { uploadMultipleToBlob } from '../../lib/imageUtils';

function estimateDataUrlSize(dataUrl: string): number {
  if (!dataUrl || !dataUrl.startsWith('data:')) return 0;
  const base64 = dataUrl.split(',')[1] || '';
  return Math.round((base64.length * 3) / 4);
}

function formatBytes(bytes: number): string {
  if (!bytes || bytes === 0) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

interface MultiImageUploaderProps {
  images: string[];
  onChange: (images: string[]) => void;
  maxImages?: number;
  label?: string;
  hint?: string;
  folder?: 'cars' | 'parts' | 'brands' | 'logos';
}

export default function MultiImageUploader({
  images,
  onChange,
  maxImages = 8,
  label = 'صور المنتج',
  hint = 'اسحب وأفلت أو اضغط لاختيار صور متعددة',
  folder = 'cars',
}: MultiImageUploaderProps) {
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState('');
  const [error, setError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFiles = useCallback(async (files: FileList | null) => {
    if (!files || files.length === 0) return;
    const remaining = maxImages - images.length;
    if (remaining <= 0) {
      setError(`الحد الأقصى ${maxImages} صور`);
      return;
    }

    setUploading(true);
    setError('');
    setUploadProgress('جاري رفع الصور...');

    try {
      const uploaded = await uploadMultipleToBlob(
        files,
        folder,
        remaining,
        (current, total) => setUploadProgress(`جاري رفع ${current} من ${total}...`)
      );

      if (uploaded.length === 0) {
        setError('فشل رفع الصور. تأكد من اتصالك بالإنترنت.');
      } else {
        onChange([...images, ...uploaded]);
        setUploadProgress(`✅ تم رفع ${uploaded.length} صورة`);
        setTimeout(() => setUploadProgress(''), 3000);
      }
    } catch {
      setError('فشل رفع الصور. تأكد من أن الملفات صور صحيحة.');
    } finally {
      setUploading(false);
    }
  }, [images, maxImages, onChange, folder]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    handleFiles(e.dataTransfer.files);
  };

  const removeImage = (idx: number) => {
    onChange(images.filter((_, i) => i !== idx));
  };

  return (
    <div className="space-y-4" dir="rtl">
      <div className="flex items-center justify-between">
        <label className="block text-sm font-bold text-white/60">{label}</label>
        <span className="text-xs text-white/30 bg-white/5 px-2 py-0.5 rounded-full font-mono">
          {images.length}/{maxImages}
        </span>
      </div>

      {/* Error */}
      {error && (
        <div className="flex items-center gap-2 text-red-400 text-xs font-bold bg-red-500/10 border border-red-500/20 rounded-xl px-4 py-2">
          <AlertCircle className="w-4 h-4 shrink-0" />
          {error}
        </div>
      )}

      {/* Drop Zone */}
      {images.length < maxImages && (
        <label
          className="relative flex flex-col items-center justify-center border-2 border-dashed border-white/10 rounded-2xl p-8 cursor-pointer hover:border-luxury-gold/40 hover:bg-white/[0.01] transition-all group text-center"
          onDrop={handleDrop}
          onDragOver={(e) => e.preventDefault()}
        >
          {uploading ? (
            <>
              <Loader2 className="w-10 h-10 text-luxury-gold animate-spin mb-3" />
              <span className="text-sm font-bold text-luxury-gold">{uploadProgress || 'جاري رفع الصور...'}</span>
              <span className="text-xs text-white/30 mt-1">يتم حفظها في التخزين السحابي الدائم</span>
            </>
          ) : (
            <>
              <div className="w-14 h-14 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center mb-4 group-hover:border-luxury-gold/30 group-hover:bg-luxury-gold/5 transition-all">
                <Upload className="w-6 h-6 text-white/20 group-hover:text-luxury-gold transition-colors" />
              </div>
              <span className="text-sm font-bold mb-1">{hint}</span>
              <span className="text-xs text-white/30">PNG، JPG، WEBP — يتم الضغط تلقائياً</span>
              <span className="text-xs text-luxury-gold/60 mt-2 font-bold">
                يمكنك تحديد {maxImages - images.length} صورة بمرة واحدة
              </span>
            </>
          )}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            multiple
            className="hidden"
            onChange={(e) => handleFiles(e.target.files)}
            disabled={uploading}
          />
        </label>
      )}

      {/* Image Grid */}
      {images.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {images.map((src, idx) => (
            <div key={idx} className="relative group rounded-xl overflow-hidden border border-white/10 bg-black/50 aspect-square">
              <img
                src={src}
                alt={`صورة ${idx + 1}`}
                className="w-full h-full object-cover"
              />
              {/* Size badge */}
              <div className="absolute bottom-1 right-1 text-[10px] font-bold text-white/60 bg-black/60 rounded px-1.5 py-0.5">
                {formatBytes(estimateDataUrlSize(src))}
              </div>
              {/* Main badge */}
              {idx === 0 && (
                <div className="absolute top-1 right-1 text-[10px] font-black text-black bg-luxury-gold rounded px-1.5 py-0.5">
                  رئيسية
                </div>
              )}
              {/* Remove button */}
              <button
                type="button"
                onClick={() => removeImage(idx)}
                className="absolute top-1 left-1 p-1.5 bg-black/70 backdrop-blur rounded-lg text-white/40 hover:text-white hover:bg-red-500 transition-all opacity-0 group-hover:opacity-100"
              >
                <X className="w-3.5 h-3.5" />
              </button>
              {/* Main label */}
              {idx === 0 && (
                <div className="absolute inset-x-0 bottom-0 h-0.5 bg-luxury-gold" />
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

/**
 * CurrencyContext - نظام العملات المتقدم
 * تحويل تلقائي بين العملات مع تحديث الأسعار
 */

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

export type Currency = 'SAR' | 'USD' | 'KRW' | 'EUR' | 'AED';

export interface CurrencyInfo {
  code: Currency;
  symbol: string;
  name: string;
  nameAr: string;
  flag: string;
}

export const CURRENCIES: Record<Currency, CurrencyInfo> = {
  SAR: { code: 'SAR', symbol: 'ر.س', name: 'Saudi Riyal', nameAr: 'ريال سعودي', flag: '🇸🇦' },
  USD: { code: 'USD', symbol: '$', name: 'US Dollar', nameAr: 'دولار أمريكي', flag: '🇺🇸' },
  KRW: { code: 'KRW', symbol: '₩', name: 'Korean Won', nameAr: 'وون كوري', flag: '🇰🇷' },
  EUR: { code: 'EUR', symbol: '€', name: 'Euro', nameAr: 'يورو', flag: '🇪🇺' },
  AED: { code: 'AED', symbol: 'د.إ', name: 'UAE Dirham', nameAr: 'درهم إماراتي', flag: '🇦🇪' },
};

interface ExchangeRates {
  [key: string]: number;
}

interface CurrencyContextType {
  currency: Currency;
  currencyInfo: CurrencyInfo;
  rates: ExchangeRates;
  setCurrency: (currency: Currency) => void;
  convert: (amount: number, from: Currency, to?: Currency) => number;
  format: (amount: number, from?: Currency) => string;
  updateRates: () => Promise<void>;
  lastUpdated: Date | null;
}

const CurrencyContext = createContext<CurrencyContextType | undefined>(undefined);

// أسعار الصرف الافتراضية (بالنسبة للريال السعودي)
const DEFAULT_RATES: ExchangeRates = {
  SAR: 1,
  USD: 0.27,    // 1 SAR = 0.27 USD
  KRW: 350,     // 1 SAR = 350 KRW
  EUR: 0.24,    // 1 SAR = 0.24 EUR
  AED: 0.98,    // 1 SAR = 0.98 AED
};

export function CurrencyProvider({ children }: { children: ReactNode }) {
  const [currency, setCurrencyState] = useState<Currency>('SAR');
  const [rates, setRates] = useState<ExchangeRates>(DEFAULT_RATES);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  // تحميل العملة المحفوظة
  useEffect(() => {
    const savedCurrency = localStorage.getItem('carx-currency') as Currency;
    if (savedCurrency && CURRENCIES[savedCurrency]) {
      setCurrencyState(savedCurrency);
    }

    // تحميل أسعار الصرف المحفوظة
    const savedRates = localStorage.getItem('carx-exchange-rates');
    const savedDate = localStorage.getItem('carx-rates-updated');
    
    if (savedRates && savedDate) {
      try {
        setRates(JSON.parse(savedRates));
        setLastUpdated(new Date(savedDate));
      } catch (error) {
        console.error('فشل تحميل أسعار الصرف:', error);
      }
    }
  }, []);

  // تحديث أسعار الصرف
  const updateRates = async () => {
    try {
      const response = await fetch('/api/exchange-rates');
      if (!response.ok) {
        // endpoint غير متوفر - استخدام الأسعار الافتراضية بهدوء
        setRates(DEFAULT_RATES);
        setLastUpdated(new Date());
        return;
      }
      const data = await response.json();

      if (data.success && data.rates) {
        setRates(data.rates);
        setLastUpdated(new Date());
        
        // حفظ في localStorage
        localStorage.setItem('carx-exchange-rates', JSON.stringify(data.rates));
        localStorage.setItem('carx-rates-updated', new Date().toISOString());
      }
    } catch {
      // endpoint غير متوفر - استخدام الأسعار الافتراضية بدون أخطاء
      setRates(DEFAULT_RATES);
      setLastUpdated(new Date());
    }
  };

  // تحديث الأسعار تلقائياً عند التحميل
  useEffect(() => {
    // تحديث إذا مر أكثر من ساعة
    const shouldUpdate = !lastUpdated || 
      (new Date().getTime() - lastUpdated.getTime()) > 3600000;

    if (shouldUpdate) {
      updateRates();
    }
  }, []);

  // تغيير العملة
  const setCurrency = (newCurrency: Currency) => {
    setCurrencyState(newCurrency);
    localStorage.setItem('carx-currency', newCurrency);
  };

  // تحويل المبلغ
  const convert = (amount: number, from: Currency, to?: Currency): number => {
    const targetCurrency = to || currency;
    
    if (from === targetCurrency) return amount;

    // تحويل إلى SAR أولاً
    const amountInSAR = amount / rates[from];
    
    // ثم تحويل إلى العملة المستهدفة
    return amountInSAR * rates[targetCurrency];
  };

  // تنسيق المبلغ
  const format = (amount: number, from: Currency = 'SAR'): string => {
    const converted = convert(amount, from);
    const info = CURRENCIES[currency];
    
    return `${converted.toLocaleString('ar-SA', {
      minimumFractionDigits: 0,
      maximumFractionDigits: 2
    })} ${info.symbol}`;
  };

  const value: CurrencyContextType = {
    currency,
    currencyInfo: CURRENCIES[currency],
    rates,
    setCurrency,
    convert,
    format,
    updateRates,
    lastUpdated,
  };

  return (
    <CurrencyContext.Provider value={value}>
      {children}
    </CurrencyContext.Provider>
  );
}

export function useCurrency() {
  const context = useContext(CurrencyContext);
  if (context === undefined) {
    throw new Error('useCurrency must be used within a CurrencyProvider');
  }
  return context;
}
